{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']
    edges = []
    for n1, n2, d in distances:
        mr = max(core_distance[n1], core_distance[n2], d)
        if n1 > n2:
            n1, n2 = n2, n1
        edges.append((mr, n1, n2))
    edges.sort(key=lambda e: (e[0], e[1], e[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, n1, n2 in edges:
        if union(n1, n2):
            mst_edges.append([n1, n2, w])
            total_weight += w
            if len(mst_edges) == len(nodes) - 1:
                break
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Graph is disconnected, cannot form MST')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}"
}
